def parse_openrtb_budget(tmax_ms, network_rtt_ms=25):
    internal_budget = max(10, tmax_ms - network_rtt_ms - 5)
    return internal_budget  # e.g., 70ms max internal compute

def recalibrate_downsampled_pctr(p_model, neg_sample_rate=0.1):
    p = min(max(p_model, 1e-7), 1.0 - 1e-7)
    return p / (p + (1.0 - p) / neg_sample_rate)

def shade_bid(true_value, floor_price, est_clearing_p50, shade_factor=0.78):
    shaded = max(floor_price, min(true_value * 0.95, est_clearing_p50 * 1.05))
    if shaded > true_value:
        return 0.0  # Unprofitable above floor
    return round(shaded, 4)

def update_pacing_rate(curr_rate, actual_spend, target_spend, kp=0.2):
    error = (target_spend - actual_spend) / max(target_spend, 1.0)
    new_rate = curr_rate * (1.0 + kp * error)
    return min(max(new_rate, 0.01), 1.0)

def emit_training_label(auction_state, click_received):
    if click_received:
        return {'auction_id': auction_state['id'], 'label': 1}
    if time.time() - auction_state['imp_ts'] > 3600:
        return {'auction_id': auction_state['id'], 'label': 0}
    return None

def is_valid_click(click_event, bloom_seen_clicks):
    if click_event['auction_id'] in bloom_seen_clicks:
        return False  # Duplicate click
    if click_event['click_delay_ms'] < 100 or click_event['is_datacenter_ip']:
        return False  # Bot / IVT signature
    return True
